.target sm_80
.address_size 64

.visible .entry softmax_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 batch_size,
    .param .u32 dim
)
{
    .reg .pred   %p;
    .reg .u32    %tid, %bid, %dim, %batch, %idx, %stride, %offset;
    .reg .u64    %input, %output, %base_in, %base_out, %addr, %offset_bytes, %row_dim, %row_dim_bytes;
    .reg .f16    %val_h;
    .reg .f32    %val_f, %max_val, %tmp, %sum, %inv_sum, %exp_f, %norm, %log2e;

