    ld.param.u64 %output,   [output_ptr];
    ld.param.u32 %batch,    [batch_size];
    ld.param.u32 %dim,      [dim];

    // Thread / block indices
    mov.u32 %tid, %tid.x;
    mov.u32 %bid, %ctaid.x;

    // Guard against excess blocks
    setp.ge.u32 %p, %bid, %batch;
    @%p ret;

    // Fixed block size (256 threads)
    mov.u32 %stride, 256;

