    // row * dim * 2 (bytes, fp16)
    mul.wide.u32 %row_dim_bytes, %row_dim, 2;

    // Base pointers for this row
    add.u64 %base_in,  %input,  %row_dim_bytes;
    add.u64 %base_out, %output, %row_dim_bytes;

    // ---------- Max reduction ----------
    mov.f32 %max_val, -1e20;          // init to very low

    mov.u32 %idx, %tid;
