    add.u64 %addr, %base_in, %offset_bytes;
    ld.global.f16 %val_h, [%addr];
    cvt.f32.f16 %val_f, %val_h;
    max.f32 %max_val, %max_val, %val_f;

    add.u32 %idx, %idx, %stride;
    bra max_loop;
