# ----------------------------------------------------------------------
import torch
import torch.nn as nn
from ptx_harness import ptx_load, ptx_launch

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # Load PTX module once
        self.module = ptx_load(PTX_SOURCE)
        # Kernel launch configuration (256 threads per block)
        self.block = (256, 1, 1)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda and x.dtype == torch.float16
        batch, dim = x.shape
        y = torch.empty_like(x)

        grid = (batch, 1, 1)   # one block per batch element
        args = [x.data_ptr(),
                y.data_ptr(),
                batch,
                dim]

        ptx_launch(self.module, "softmax_kernel", grid, self.block, args)
